<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}
final class ReturnReview {
 static function closed(array $row):bool{
  if(!empty($row['redelivery'])||!empty($row['refund_complete']))return true;
  $amount=$row['gross_amount_cents']??null;
  return $amount!==null&&(int)$amount>0&&array_sum(array_column($row['refunds']??[],'refund_amount_cents'))>=(int)$amount;
 }

 static function redelivered(\PDO $db,array $actor,string $returned,string $replacement):array{permit($actor,'operate');return transaction($db,function()use($db,$actor,$returned,$replacement){
  if($returned===$replacement)throw new Problem('AWB-urile trebuie să fie diferite.');
  $s=one($db,'SELECT * FROM fan_shipments WHERE awb=? FOR UPDATE',[$returned]);$next=one($db,'SELECT * FROM fan_shipments WHERE awb=? FOR UPDATE',[$replacement]);
  if(!$s||!$next||$s['delivery_status']!=='returned'||$next['delivery_status']!=='delivered')throw new Problem('Sunt necesare un AWB returnat și un AWB livrat.');
  $old=one($db,"SELECT id,source_hashes_json FROM decisions WHERE shipment_id=? AND action='return_redelivered' AND active=1 FOR UPDATE",[$s['id']]);
  if($old){if((json_decode($old['source_hashes_json'],true)['replacement_awb']??'')!==$replacement)throw new Problem('Există altă relivrare confirmată.');return ['saved'=>true,'repeated'=>true,'decision'=>$old['id']];}
  $ret=one($db,'SELECT * FROM shipment_returns WHERE shipment_id=? FOR UPDATE',[$s['id']]);
  if($ret&&one($db,'SELECT id FROM refunds WHERE return_id=?',[$ret['id']]))throw new Problem('Există deja o restituire înregistrată; trebuie verificată separat.');
  $proof=['returned_awb'=>$returned,'replacement_awb'=>$replacement,'replacement_shipment_id'=>(int)$next['id'],'shipment_hash'=>$s['source_hash'],'replacement_hash'=>$next['source_hash'],'replacement_date'=>$next['awb_date']];
  $id=decision($db,'return_redelivered',['shipment'=>$s['id']],$proof,'Utilizatorul confirmă livrarea cu alt AWB. Nu este necesară restituirea plății; ambele expedieri originale se păstrează.',$actor,'redelivery:'.bin2hex(random_bytes(16)));
  if($ret)query($db,"UPDATE shipment_returns SET status='redelivered',decision_id=? WHERE id=?",[$id,$ret['id']]);else query($db,"INSERT INTO shipment_returns(shipment_id,status,decision_id) VALUES(?,'redelivered',?)",[$s['id'],$id]);
  audit($db,'return_redelivered',$proof,$actor,$id);return ['saved'=>true,'decision'=>$id];
 });}

 static function partial(\PDO $db,array $actor,string $external,int $amount,string $company):array{permit($actor,'operate');return transaction($db,function()use($db,$actor,$external,$amount,$company){$p=one($db,'SELECT * FROM netopia_payments WHERE canonical_external_id=? FOR UPDATE',[$external]);if(!$p||$amount<=0||$amount>=(int)$p['gross_amount_cents'])throw new Problem('Sumă parțială invalidă.');$old=self::pending($db,(int)$p['id']);if($old){if($old['amount_cents']!==$amount||$old['display_name']!==$company)throw new Problem('Există altă sumă în verificare.');return ['saved'=>true,'repeated'=>true];}if(one($db,'SELECT payment_id FROM '.Topups::links().' l WHERE payment_id=?',[$p['id']]))throw new Problem('Plata are deja o rezoluție.');$id=decision($db,'netopia_return_partial_review',['payment'=>$p['id']],['resource_hash'=>$p['source_hash'],'amount_cents'=>$amount,'display_name'=>$company,'original_amount_cents'=>(int)$p['gross_amount_cents']],'Sumă parțială mutată temporar la retururi NETOPIA, la cererea utilizatorului. Restituirea nu este confirmată.',$actor,'partial-return:'.bin2hex(random_bytes(16)));audit($db,'netopia_return_partial_review',['payment'=>$external,'amount_cents'=>$amount,'display_name'=>$company],$actor,$id);return ['saved'=>true,'decision'=>$id];});}
 static function pending(\PDO $db,int $payment):?array{$r=one($db,"SELECT source_hashes_json FROM decisions WHERE payment_id=? AND action='netopia_return_partial_review' AND active=1",[$payment]);return $r?json_decode($r['source_hashes_json'],true):null;}
 static function hold(\PDO $db,array $actor,array $order,string $feedHash):array{permit($actor,'operate');if(($order['_payment_status']??'')!=='Plata returnata')throw new Problem('SITE nu indică plata returnată.');return transaction($db,function()use($db,$actor,$order,$feedHash){$p=one($db,'SELECT * FROM netopia_payments WHERE canonical_external_id=? FOR UPDATE',[$order['id']]);if(!$p||(int)$p['gross_amount_cents']!==(int)$order['amount_cents'])throw new Problem('Plata nu corespunde comenzii.');$old=one($db,"SELECT id FROM decisions WHERE payment_id=? AND action='netopia_return_review' AND active=1",[$p['id']]);if($old)return ['saved'=>true,'repeated'=>true];if(one($db,'SELECT payment_id FROM '.Topups::links().' l WHERE payment_id=?',[$p['id']]))throw new Problem('Plata are deja o rezoluție.');$o=one($db,'SELECT id FROM site_orders WHERE order_number=?',[$order['id']]);$id=decision($db,'netopia_return_review',['payment'=>$p['id'],'order'=>$o['id']??null],['resource_hash'=>$p['source_hash'],'feed_hash'=>$feedHash,'order_status'=>$order['_delivery_status']??'','payment_status'=>$order['_payment_status'],'amount_cents'=>(int)$p['gross_amount_cents']],'Mutată temporar la retururi NETOPIA la cererea utilizatorului. SITE indică plata returnată; restituirea bancară nu este confirmată.',$actor,'return-review:'.bin2hex(random_bytes(16)));audit($db,'netopia_return_review',['payment'=>$order['id']],$actor,$id);return ['saved'=>true,'decision'=>$id];});}
 static function rows(\PDO $db):array{$out=query($db,"SELECT p.id AS payment_id,p.client AS recipient,p.canonical_external_id,p.gross_amount_cents,p.source_hash AS payment_source_hash,d.reason,d.action,d.source_hashes_json FROM decisions d JOIN netopia_payments p ON p.id=d.payment_id WHERE d.action IN ('netopia_return_review','netopia_return_partial_review') AND d.active=1 ORDER BY d.id DESC")->fetchAll();foreach($out as &$r){if($r['action']==='netopia_return_partial_review'){$proof=json_decode($r['source_hashes_json'],true);$r['original_amount_cents']=$r['gross_amount_cents'];$r['gross_amount_cents']=$proof['amount_cents'];$r['recipient']=$proof['display_name'];$r['partial_return_review']=true;}$r['refunds']=query($db,'SELECT refund_amount_cents,refund_date,reference,evidence_type FROM refunds WHERE payment_id=?',[$r['payment_id']])->fetchAll();$refunded=array_sum(array_column($r['refunds'],'refund_amount_cents'));$r['refund_complete']=$refunded>=(int)$r['gross_amount_cents'];$r+=['id'=>null,'awb'=>null,'method'=>'NETOPIA','invoice_number'=>null,'return_review'=>true];}return $out;}
}
